<template><label class="block"><span class="label">{{ label }}</span><select class="input mt-1" :value="modelValue" @change="$emit('update:modelValue', $event.target.value)"><option value="">Select...</option><option v-for="option in options" :key="option.id || option" :value="option.id || option">{{ option.name || option }}</option></select><span v-if="error" class="mt-1 block text-xs font-bold text-red-600">{{ error }}</span></label></template>
<script>export default { props: { label: String, modelValue: [String, Number], options: Array, error: String }, emits: ['update:modelValue'] }</script>